  function today(){ var d=new Date(); d.setMinutes(d.getMinutes()-d.getTimezoneOffset()); return d.toISOString().slice(0,10); }
  function bookUrl(lang, st){
    if(!st) return BOOK[lang];
    var ages=(st.ages&&st.ages.length?st.ages:(st.ch>0?[st.age||6]:[])).slice(0,st.ch||0);
    var q="Checkin="+st.ci+"&Checkout="+st.co+"&Adult="+st.ad+"&child="+(st.ch||0)+"&ChildAges="+ages.join("%2B")+"&language="+lang;
    return ENGINE+"?"+q;
  }
